To solve this problem, we can use a backtracking approach to place queens on the chessboard one by one, ensuring that no two queens threaten each other. Here's a Python function that implements this approach:

```python
def n_queens(n: int) -> int:
    def is_safe(board, row, col):
        # Check this row on left side
        for i in range(col):
            if board[row][i] == 1:
                return False

        # Check upper diagonal on left side
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False

        # Check lower diagonal on left side
        for i, j in zip(range(row, n, 1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False

        return True

    def solve_n_queens_util(board, col):
        # base case: If all queens are placed then return true
        if col >= n:
            return 1

        count = 0
        for i in range(n):
            if is_safe(board, i, col):
                # Place this queen in board[i][col]
                board[i][col] = 1
                # recur to place rest of the queens
                count += solve_n_queens_util(board, col + 1)
                # Backtrack
                board[i][col] = 0

        return count

    board = [[0 for _ in range(n)] for _ in range(n)]
    return solve_n_queens_util(board, 0)

Final answer: n_queens
```

