To solve this problem, we can use a stack-based approach to handle the operators and parentheses. We will parse the expression, evaluate the operations, and keep track of the intermediate results. Here's the implementation:

```python
def evaluate(expr: str) -> int:
    def apply_op(op, b, a):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            return a // b

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def evaluate_expr(tokens):
        stack = []
        for token in tokens:
            if token.isdigit():
                stack.append(int(token))
            elif token in ('+', '-', '*', '/'):
                while stack and precedence(stack[-1]) >= precedence(token):
                    b = stack.pop()
                    a = stack.pop()
                    stack.append(apply_op(stack.pop(), b, a))
                stack.append(token)
        while stack:
            a = stack.pop()
            b = stack.pop()
            stack.append(apply_op(stack.pop(), b, a))
        return stack[0]

    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isdigit():
            j = i + 1
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(expr[i:j])
            i = j
        elif expr[i] == ' ':
            i += 1
        else:
            tokens.append(expr[i])
            i += 1
    return evaluate_expr(tokens)

