```python
def longest_palindrome(s: str) -> str:
    if not s:
        return ''

    n = len(s)
    dp = [[False] * n for _ in range(n)]
    start, end = 0, 0

    for i in range(n):
        dp[i][i] = True
        for j in range(i):
            dp[j][i] = (s[j] == s[i]) and (i - j < 2 or dp[j + 1][i - 1])
            if dp[j][i] and i - j > end - start:
                start, end = j, i

    return s[start:end + 1]

