def paths_with_obstacles(grid: list[list[int]]) -> int:
    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]

    if grid[0][0] == 0:
        dp[0][0] = 1

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                dp[i][j] = 0
            elif i > 0 and j > 0:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            elif i == 0 and j > 0:
                dp[i][j] = dp[i][j-1]
            elif j == 0 and i > 0:
                dp[i][j] = dp[i-1][j]

