def paths_with_obstacles(grid: list[list[int]]) -> int:
    # Get dimensions of the grid
    rows, cols = len(grid), len(grid[0])

    # Create a DP table to store the number of paths to each cell
    dp = [[0] * cols for _ in range(rows)]

    # If the start cell is blocked, there are no paths
    if grid[0][0] == 1:
        return 0

    # Initialize the start cell
    dp[0][0] = 1

    # Fill the first row
    for col in range(1, cols):
        if grid[0][col] == 0:
            dp[0][col] = dp[0][col - 1]

    # Fill the first column
    for row in range(1, rows):
        if grid[row][0] == 0:
            dp[row][0] = dp[row - 1][0]

    # Fill the rest of the DP table
    for row in range(1, rows):
        for col in range(1, cols):
            if grid[row][col] == 0:
                dp[row][col] = dp[row - 1][col] + dp[row][col - 1]

    # The bottom-right cell contains the number of paths
    return dp[-1][-1]

