To solve the N-Queens problem, we can use backtracking. The idea is to try placing a queen in each row and ensure that no two queens threaten each other. We can use a list to keep track of the column positions of queens in the current row and recursively try to place queens in the next row.

Here is the implementation:

```python
def n_queens(n: int) -> int:
    def is_safe(board, row, col):
        # Check this row on left side
        for i in range(col):
            if board[row][i] == 1:
                return False

        # Check upper diagonal on left side
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False

        # Check lower diagonal on left side
        for i, j in zip(range(row, n, 1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False

        return True

    def solve_n_queens_util(board, col):
        # base case: If all queens are placed then return true
        if col >= n:
            return 1

        res = 0
        for i in range(n):
            if is_safe(board, i, col):
                board[i][col] = 1
                res += solve_n_queens_util(board, col + 1)
                board[i][col] = 0  # backtrack

        return res

    board = [[0 for _ in range(n)] for _ in range(n)]
    return solve_n_queens_util(board, 0)

