def evaluate(expr: str) -> int:
    def tokenize(expr):
        i, n = 0, len(expr)
        while i < n:
            if expr[i].isspace():
                i += 1
                continue
            if expr[i].isdigit():
                j = i + 1
                while j < n and expr[j].isdigit():
                    j += 1
                yield int(expr[i:j])
                i = j
            else:
                yield expr[i]
                i += 1

    def evaluate_expression(tokens):
        stack = []
        for token in tokens:
            if isinstance(token, int):
                stack.append(token)
            else:
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(a // b)
        return stack[0]

    tokens = list(tokenize(expr))
    return evaluate_expression(tokens)

