def precedence(op):
    if op in ('+', '-'):
        return 1
    if op in ('*', '/'):
        return 2
    return 0

def apply_operator(operators, values):
    operator = operators.pop()
    right = values.pop()
    left = values.pop()
    if operator == '+':
        values.append(left + right)
    elif operator == '-':
        values.append(left - right)
    elif operator == '*':
        values.append(left * right)
    elif operator == '/':
        values.append(int(left / right))

def evaluate_expression(expression):
    tokens = expression.replace(' ', '')
    operators = []
    values = []
    i = 0
    while i < len(tokens):
        if tokens[i].isdigit():
            j = i
            while j < len(tokens) and tokens[j].isdigit():
                j += 1
            values.append(int(tokens[i:j]))
            i = j - 1
        elif tokens[i] == '(':
            operators.append(tokens[i])
        elif tokens[i] == ')':
            while operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()  # Remove '('
        else:
            while (operators and operators[-1] != '(' and
                   precedence(tokens[i]) <= precedence(operators[-1])):
                apply_operator(operators, values)
            operators.append(tokens[i])
        i += 1
    while operators:
        apply_operator(operators, values)
    return values[0]

def evaluate(expr: str) -> int:
