from collections import deque

def sliding_max(nums: list[int], k: int) -> list[int]:
    if k == 0:
        return []
    deq = deque()
    max_values = []

    for i, num in enumerate(nums):
        # Remove indices that are out of the current window
        while deq and deq[0] < i - k + 1:
            deq.popleft()

        # Remove indices whose corresponding values are less than the current number
        while deq and nums[deq[-1]] < num:
            deq.pop()

        # Add current index to the deque
        deq.append(i)

        # The first element in the deque is the index of the max value for the current window
        if i >= k - 1:
            max_values.append(nums[deq[0]])

    return max_values

