To solve this problem, we can use a backtracking algorithm to count the number of valid ways to place n queens on an n x n chessboard. We will use a recursive approach to place queens column by column and check for conflicts with previously placed queens.

Here's a Python function that implements this approach:

```python
def n_queens(n: int) -> int:
    def is_safe(board, row, col):
        # Check this row on left side
        for i in range(col):
            if board[row][i] == 'Q':
                return False

        # Check upper diagonal on left side
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j] == 'Q':
                return False

        # Check lower diagonal on left side
        for i, j in zip(range(row, n, 1), range(col, -1, -1)):
            if board[i][j] == 'Q':
                return False

        return True

    def solve_n_queens(board, col):
        if col >= n:
            return 1

        count = 0
        for i in range(n):
            if is_safe(board, i, col):
                board[i][col] = 'Q'
                count += solve_n_queens(board, col + 1)
                board[i][col] = '.'
        return count

    board = [['.' for _ in range(n)] for _ in range(n)]
    return solve_n_queens(board, 0)
